public class Main {
    interface Employee { String name(); double monthlyPay(); }
    record SalariedEmployee(String name, double annualSalary) implements Employee {
        public double monthlyPay() {
            if (annualSalary < 0) throw new IllegalArgumentException("Salary cannot be negative");
            return annualSalary / 12.0;
        }
    }
    public static void main(String[] args) {
        Employee employee = new SalariedEmployee("Ravi", 600000.0);
        System.out.printf("%s: %.2f per month%n", employee.name(), employee.monthlyPay());
    }
}
